import React, { useEffect } from 'react';
import { useParams } from 'react-router-dom';
import { FitAddon } from '@xterm/addon-fit';
import { useXTerm } from 'react-xtermjs';
import 'xterm/css/xterm.css';

const TerminalComponent = () => {
  const { containerId } = useParams(); // Retrieve container ID from URL params
  const { instance, ref } = useXTerm(); // `useXTerm` provides xterm instance and div ref
  const fitAddon = new FitAddon(); // FitAddon instance for xterm.js resizing

  useEffect(() => {
    // Load the fit addon for dynamic resizing
    instance?.loadAddon(fitAddon);

    // Function to handle terminal resizing
    const handleResize = () => fitAddon.fit();

    // Set up WebSocket connection
    const socket = new WebSocket('ws://localhost:3001');

    socket.onopen = () => {
      console.log('WebSocket connection established');
      // Send initial command to start a shell session in the container
      socket.send(JSON.stringify({ containerId, cmd: '/bin/sh' }));
    };

    // Handle incoming messages from WebSocket (output from Docker container)
    socket.onmessage = (event) => {
      const message = JSON.parse(event.data);
      if (message.output) {
        instance?.write(message.output); // Display output in terminal
      } else if (message.error) {
        instance?.write(`\x1B[31m${message.error}\x1B[0m`); // Display errors in red
      } else if (message.message) {
        instance?.write(`${message.message}\n`);
      }
    };

    // Handle terminal input
    instance?.onData((input) => {
      if (socket.readyState === WebSocket.OPEN) {
        socket.send(JSON.stringify({ containerId, cmd: input })); // Send input to container
      } else {
        instance?.writeln('Connection closed. Unable to send data.');
      }
    });

    // Write a welcome message to the terminal
    instance?.writeln('Welcome to react-xtermjs!');
    instance?.writeln(`Connected to container: ${containerId}`);

    // Add resize event listener
    window.addEventListener('resize', handleResize);

    // Fit the terminal to its container
    fitAddon.fit();

    // Cleanup on component unmount
    return () => {
      socket.close();
      window.removeEventListener('resize', handleResize);
    };
  }, [instance, containerId]);

  return (
    <div
      ref={ref}
      style={{
        width: '100%',
        height: '100%',
        backgroundColor: 'black',
        color: 'white',
      }}
    />
  );
};

export default TerminalComponent;
